	HIGHT_ENC(w, 25, 0, 7, 6, 5, 4, 3, 2, 1, varNames...)
	HIGHT_ENC(w, 26, 7, 6, 5, 4, 3, 2, 1, 0, varNames...)
	HIGHT_ENC(w, 27, 6, 5, 4, 3, 2, 1, 0, 7, varNames...)
