func encrypt1(w io.Writer) {
	fmt.Fprintln(
		w,
		`
func encryptGo(pdwRoundKey *roundKeys, dst, src *block1) {
	x0 := src[0] + pdwRoundKey[0]
	x1 := src[1]
	x2 := src[2] ^ pdwRoundKey[1]
	x3 := src[3]
	x4 := src[4] + pdwRoundKey[2]
	x5 := src[5]
	x6 := src[6] ^ pdwRoundKey[3]
	x7 := src[7]`,
	)
	encrypt(w, "x")
	fmt.Fprintln(w, `

	dst[0] = x1 + pdwRoundKey[4]
	dst[1] = x2
	dst[2] = x3 ^ pdwRoundKey[5]
	dst[3] = x4
	dst[4] = x5 + pdwRoundKey[6]
	dst[5] = x6
	dst[6] = x7 ^ pdwRoundKey[7]
	dst[7] = x0
}`)
}

func decrypt1(w io.Writer) {
	fmt.Fprintln(
		w,
		`
func decryptGo(pdwRoundKey *roundKeys, dst, src *block1) {
	x0 := src[7]
	x1 := src[0] - pdwRoundKey[4]
	x2 := src[1]
	x3 := src[2] ^ pdwRoundKey[5]
	x4 := src[3]
	x5 := src[4] - pdwRoundKey[6]
	x6 := src[5]
	x7 := src[6] ^ pdwRoundKey[7]`,
	)
	decrypt(w, "x")
	fmt.Fprintln(w, `

	dst[0] = x0 - pdwRoundKey[0]
	dst[1] = x1
	dst[2] = x2 ^ pdwRoundKey[1]
	dst[3] = x3
	dst[4] = x4 - pdwRoundKey[2]
	dst[5] = x5
	dst[6] = x6 ^ pdwRoundKey[3]
	dst[7] = x7
}`)
}

func encrypt2(w io.Writer) {
	fmt.Fprintln(
		w,
		`
func encrypt2Go(pdwRoundKey *roundKeys, dst, src *block2) {
	a0 := src[0] + pdwRoundKey[0]
	a1 := src[1]
	a2 := src[2] ^ pdwRoundKey[1]
	a3 := src[3]
	a4 := src[4] + pdwRoundKey[2]
	a5 := src[5]
	a6 := src[6] ^ pdwRoundKey[3]
	a7 := src[7]

	b0 := src[8+0] + pdwRoundKey[0]
	b1 := src[8+1]
	b2 := src[8+2] ^ pdwRoundKey[1]
	b3 := src[8+3]
	b4 := src[8+4] + pdwRoundKey[2]
	b5 := src[8+5]
	b6 := src[8+6] ^ pdwRoundKey[3]
	b7 := src[8+7]`,
	)
	encrypt(w, "a", "b")
	fmt.Fprintln(w, `

	dst[0] = a1 + pdwRoundKey[4]
	dst[1] = a2
	dst[2] = a3 ^ pdwRoundKey[5]
	dst[3] = a4
	dst[4] = a5 + pdwRoundKey[6]
	dst[5] = a6
	dst[6] = a7 ^ pdwRoundKey[7]
	dst[7] = a0

	dst[8+0] = b1 + pdwRoundKey[4]
	dst[8+1] = b2
	dst[8+2] = b3 ^ pdwRoundKey[5]
	dst[8+3] = b4
	dst[8+4] = b5 + pdwRoundKey[6]
	dst[8+5] = b6
	dst[8+6] = b7 ^ pdwRoundKey[7]
	dst[8+7] = b0
}`)
}

func decrypt2(w io.Writer) {
	fmt.Fprintln(
		w,
		`
func decrypt2Go(pdwRoundKey *roundKeys, dst, src *block2) {
	a0 := src[7]
	a1 := src[0] - pdwRoundKey[4]
	a2 := src[1]
	a3 := src[2] ^ pdwRoundKey[5]
	a4 := src[3]
	a5 := src[4] - pdwRoundKey[6]
	a6 := src[5]
	a7 := src[6] ^ pdwRoundKey[7]

	b0 := src[8+7]
	b1 := src[8+0] - pdwRoundKey[4]
	b2 := src[8+1]
	b3 := src[8+2] ^ pdwRoundKey[5]
	b4 := src[8+3]
	b5 := src[8+4] - pdwRoundKey[6]
	b6 := src[8+5]
	b7 := src[8+6] ^ pdwRoundKey[7]`,
	)
	decrypt(w, "a", "b")
	fmt.Fprintln(w, `

	dst[0] = a0 - pdwRoundKey[0]
	dst[1] = a1
	dst[2] = a2 ^ pdwRoundKey[1]
	dst[3] = a3
	dst[4] = a4 - pdwRoundKey[2]
	dst[5] = a5
	dst[6] = a6 ^ pdwRoundKey[3]
	dst[7] = a7

	dst[8+0] = b0 - pdwRoundKey[0]
	dst[8+1] = b1
	dst[8+2] = b2 ^ pdwRoundKey[1]
	dst[8+3] = b3
	dst[8+4] = b4 - pdwRoundKey[2]
	dst[8+5] = b5
	dst[8+6] = b6 ^ pdwRoundKey[3]
	dst[8+7] = b7
}`)
}
